CREATE TABLE tenants(id text PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),user_subject text NOT NULL,role text NOT NULL,status text NOT NULL);
CREATE TABLE source_artifacts(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),environment text NOT NULL,source_system text NOT NULL,source_record_id text NOT NULL,object_key text NOT NULL,sha256 text NOT NULL,media_type text NOT NULL,received_at timestamptz NOT NULL,bytes bytea NOT NULL);
CREATE TABLE invoices(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),environment text NOT NULL,source_system text NOT NULL,source_record_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,environment,source_system,source_record_id));
CREATE TABLE invoice_revisions(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),invoice_id text NOT NULL REFERENCES invoices(id),revision_number integer NOT NULL,schema_version text NOT NULL,canonical_json jsonb NOT NULL,canonical_sha256 text NOT NULL,source_artifact_id text NOT NULL REFERENCES source_artifacts(id),status text NOT NULL DEFAULT 'NORMALIZED',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(invoice_id,revision_number));
CREATE TABLE recipient_profiles(id text PRIMARY KEY,tenant_id text REFERENCES tenants(id),recipient_key text NOT NULL,status text NOT NULL);
CREATE TABLE recipient_profile_versions(id text PRIMARY KEY,profile_id text NOT NULL REFERENCES recipient_profiles(id),version text NOT NULL,rules_json jsonb NOT NULL,source_evidence_json jsonb NOT NULL,effective_from timestamptz,reviewed_at timestamptz,sha256 text NOT NULL);
CREATE TABLE validation_runs(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),revision_id text NOT NULL REFERENCES invoice_revisions(id),profile_version_id text,rule_manifest_json jsonb NOT NULL,engine_version text NOT NULL,status text NOT NULL,kind text NOT NULL,canonical_sha256 text NOT NULL,xml_sha256 text,raw_report text,findings jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,dedupe_key text NOT NULL,UNIQUE(tenant_id,dedupe_key));
CREATE TABLE validation_findings(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),validation_run_id text NOT NULL REFERENCES validation_runs(id),stable_code text NOT NULL,severity text NOT NULL,layer text NOT NULL,canonical_path text NOT NULL,source_path text,external_rule_id text,message_key text NOT NULL,parameters_json jsonb NOT NULL);
CREATE TABLE approvals(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),revision_id text NOT NULL REFERENCES invoice_revisions(id),validation_run_id text NOT NULL REFERENCES validation_runs(id),profile_version_id text,approver_subject text NOT NULL,approved_at timestamptz NOT NULL DEFAULT now(),canonical_sha256 text NOT NULL,UNIQUE(tenant_id,revision_id,validation_run_id));
CREATE TABLE generation_artifacts(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),revision_id text NOT NULL REFERENCES invoice_revisions(id),approval_id text NOT NULL REFERENCES approvals(id),syntax text NOT NULL,profile text NOT NULL,generator_version text NOT NULL,object_key text NOT NULL,sha256 text NOT NULL,bytes bytea NOT NULL,validation_run_id text REFERENCES validation_runs(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,approval_id,generator_version));
CREATE TABLE evidence_manifests(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),revision_id text NOT NULL REFERENCES invoice_revisions(id),validation_run_id text NOT NULL REFERENCES validation_runs(id),manifest jsonb NOT NULL,sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,revision_id,validation_run_id));
CREATE TABLE jobs(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),type text NOT NULL,dedupe_key text NOT NULL,state text NOT NULL DEFAULT 'PENDING',payload_json jsonb NOT NULL,attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,last_error_code text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,dedupe_key));
CREATE TABLE idempotency_records(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),route_key text NOT NULL,idempotency_key text NOT NULL,request_sha256 text NOT NULL,response_status integer NOT NULL,response_json jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,route_key,idempotency_key));
CREATE TABLE audit_events(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),actor_subject text NOT NULL,action text NOT NULL,resource_type text NOT NULL,resource_id text NOT NULL,request_id text NOT NULL,metadata_json jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX revision_tenant ON invoice_revisions(tenant_id,invoice_id,revision_number DESC);
CREATE INDEX artifact_tenant ON generation_artifacts(tenant_id,revision_id);
CREATE INDEX validation_tenant ON validation_runs(tenant_id,revision_id,created_at DESC);
CREATE INDEX job_claim ON jobs(state,available_at);
CREATE FUNCTION protect_revision() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.canonical_json IS DISTINCT FROM OLD.canonical_json OR NEW.canonical_sha256 IS DISTINCT FROM OLD.canonical_sha256 OR NEW.source_artifact_id IS DISTINCT FROM OLD.source_artifact_id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.invoice_id IS DISTINCT FROM OLD.invoice_id OR NEW.revision_number IS DISTINCT FROM OLD.revision_number THEN RAISE EXCEPTION 'Immutable revision'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_revision BEFORE UPDATE ON invoice_revisions FOR EACH ROW EXECUTE FUNCTION protect_revision();
CREATE FUNCTION protect_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable artifact'; END $$;
CREATE TRIGGER immutable_source BEFORE UPDATE ON source_artifacts FOR EACH ROW EXECUTE FUNCTION protect_immutable();
CREATE TRIGGER immutable_generation BEFORE UPDATE ON generation_artifacts FOR EACH ROW EXECUTE FUNCTION protect_immutable();
CREATE TRIGGER immutable_evidence BEFORE UPDATE ON evidence_manifests FOR EACH ROW EXECUTE FUNCTION protect_immutable();
